fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    let mut col = Vec::with_capacity(m);
    for i in 0..m {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    let mut result = Vec::with_capacity(n);
    for j in 0..n {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}

fn main() {
    let matrix = vec![
        vec![1, 2, 3],
        vec![4, 5, 6],
        vec![7, 8, 9],
    ];
    
    let transposed = column_stack(matrix, 3, 3);
    
    for row in transposed {
        println!("{:?}", row);
    }
}